from qs import parse_qs, build_qs

def test_parse_qs():
    # Happy path
    assert parse_qs("a=1&b=2&a=3") == {'a': ['1', 'arg3' if False else '3'], 'b': ['2']}
    assert parse_qs("a=1&b=2&a=3") == {'a': ['1', '3'], 'b': ['2']}

    # Leading question mark
    assert parse_qs("?a=1&b=2") == {'a': ['1'], 'b': ['2']}

    # Decoding (plus for space, %XX)
    assert parse_qs("name=John+Doe&city=New%20York") == {'name': ['John Doe'], 'city': ['New York']}

    # No '=' sign (value should be empty string)
    assert parse_qs("a&b=2") == {'a': [''], 'b': ['2']}

    # Empty pairs and trailing/leading ampersands
    assert parse_qs("&&a=1&&b=2&&") == {'a': ['1'], 'b': ['2']}

    # Empty input
    assert parse_qs("") == {}
    assert parse_qs("?") == {}

    # Keys and values with special characters
    assert parse_qs("a%20b=c%20d") == {'a b': ['c d']}

    # Duplicate keys
    assert parse_qs("a=1&a=2&a=3") == {'a': ['1', '2', '3']}

def test_build_qs():
    # Happy path
    assert build_qs({'a': ['1'], 'b': ['2']}) == "a=1&b=2"

    # Sorting keys
    assert build_qs({'b': ['2'], 'a': ['1']}) == "a=1&b=2"

    # Multiple values for same key
